// Unified Inbound Envelope, Sanitization & Omnichannel Guardrails (Gap 24, 9, 5)
const rawInput = $input.first().json.body || $input.first().json;
const message = (rawInput.message || rawInput.chatInput || rawInput.text || 'Hello').trim();
const senderId = rawInput.senderId || rawInput.chatId || rawInput.phone || 'ANONYMOUS';
const channel = rawInput.channel || (rawInput.chatId ? 'TELEGRAM' : (rawInput.phone ? 'WHATSAPP' : 'WEB'));
const userRole = rawInput.userRole || (channel === 'TELEGRAM' && rawInput.isAuthorized ? 'ADMIN' : 'CUSTOMER');
const traceId = `tr_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`;
const authToken = rawInput.authToken || '';

// Injection & PII Sanitization
const sanitized = message.replace(/<script.*?>.*?<\/script>/gi, '').replace(/drop table|delete from/gi, '[BLOCKED]').trim();

return [{
  json: {
    traceId: traceId,
    channel: channel,
    senderId: senderId,
    userRole: userRole,
    message: sanitized,
    productId: rawInput.productId || 1,
    currency: rawInput.currency || 'USD',
    authToken: authToken,
    timestamp: new Date().toISOString()
  }
}];

// Rate-limited response — sent back on the sender's own channel instead of reaching the Supervisor (Gap 9)
const envelope = $('2. Unified Inbound Envelope & Guardrails').first().json;
return [{
  json: {
    traceId: envelope.traceId,
    channel: envelope.channel,
    senderId: envelope.senderId,
    reply: 'You are sending messages too quickly. Please wait a moment and try again.',
    status: 'RATE_LIMITED'
  }
}];

// Daily LLM budget cap reached (Gap 6 & 16) — queue for a human instead of calling the paid API further
const envelope = $('2. Unified Inbound Envelope & Guardrails').first().json;
return [{
  json: {
    traceId: envelope.traceId,
    channel: envelope.channel,
    senderId: envelope.senderId,
    reply: 'Thanks for your message — our team will follow up shortly.',
    status: 'BUDGET_CAP_REACHED_QUEUED_FOR_HUMAN'
  }
}];

