// Supervisor Output Evaluator & HITL Decision Gate (Gap 2 & Gap 28)
const resp = $input.first().json;
const confidence = parseFloat(resp.confidenceScore || 0.95);
const amountMAD = parseFloat(resp.actionAmountMAD || 0);

const isApprovalRequired = (amountMAD >= 5000);
const isLowConfidence = (confidence < 0.70);

return [{
  json: {
    reply: resp.reply || resp.output || 'I have processed your request.',
    confidence: confidence,
    isLowConfidence: isLowConfidence,
    isApprovalRequired: isApprovalRequired,
    status: isApprovalRequired ? 'PENDING_APPROVAL' : (isLowConfidence ? 'ESCALATED_HITL' : 'SUCCESS')
  }
}];

// Generate HITL Support Queue Handoff (Gap 2)
return [{
  json: {
    ticketType: 'SUPPORT_HANDOFF',
    ticketId: `TCK-${Date.now().toString().slice(-6)}`,
    message: 'Je transfère votre demande à notre équipe client ZeyTech pour un traitement prioritaire.',
    status: 'ESCALATED_TO_HUMAN'
  }
}];

// Generate Manager Telegram Authorization Request (Gap 28)
return [{
  json: {
    ticketType: 'MANAGER_APPROVAL_GATE',
    telegramAlert: '⚠️ *HIGH-VALUE ACTION APPROVAL REQUIRED (> 5,000 MAD)*\nReply /approve or /reject to authorize.',
    status: 'PENDING_MANAGER_APPROVAL'
  }
}];

// Central Event Processor & Deduplication Fan-Out (Gap 26 & Gap 8)
const payload = $input.first().json.body || $input.first().json;
const isCron = !!payload.field;
const eventType = isCron ? 'DAILY_CRON_REPORT' : (payload.eventType || payload.event || 'SALE_COMPLETED');

// Stable idempotency key: prefer an event ID the source system already sent (Gap 8),
// fall back to a generated one only for cron (which has no natural external ID)
const eventId = payload.eventId || (isCron ? `cron_${new Date().toISOString().slice(0,13)}` : `evt_${Date.now()}`);

return [{
  json: {
    eventId: eventId,
    eventType: eventType,
    payload: payload,
    timestamp: new Date().toISOString()
  }
}];

// Duplicate event — already processed, discard without re-triggering notifications (Gap 8)
const evt = $('8. Central Event Processor & Deduplication Router').first().json;
return [{
  json: {
    eventId: evt.eventId,
    eventType: evt.eventType,
    status: 'DUPLICATE_DISCARDED'
  }
}];

