// Agent 15: Dedicated Notification Agent & Multi-Lingual Formatter (Gap 25, 37, 7)
const evt = $('8. Central Event Processor & Deduplication Router').first().json;
const kpi = $input.first().json;
const lang = evt.payload.language || 'DARIJA';

let alertTitle = '🎉 *NEW ZEYTECH SALE COMPLETED!* 🚀';
let alertBody = kpi.reply || 'ZeyTech operations nominal.';

if (lang === 'DARIJA') {
  alertTitle = '🎉 *تم تسجيل طلب جديد بنجاح في ZeyTech!* 🚀';
}

return [{
  json: {
    agent: 'NOTIFICATION_AGENT',
    title: alertTitle,
    body: alertBody,
    channels: ['TELEGRAM_BOT', 'WHATSAPP_BUSINESS', 'IN_APP_DASHBOARD'],
    timestamp: new Date().toISOString()
  }
}];

// Dispatch to Telegram Bot Gateway (Gap 25)
const notif = $('Agent 15: Dedicated Notification Agent').first().json;
return [{
  json: {
    channel: 'TELEGRAM_BOT',
    telegramText: `${notif.title}\n\n${notif.body}`,
    status: 'DISPATCHED_TO_TELEGRAM'
  }
}];

// Dispatch to WhatsApp Business Gateway (Gap 14 & Gap 25)
const notif = $('Agent 15: Dedicated Notification Agent').first().json;
return [{
  json: {
    channel: 'WHATSAPP_BUSINESS',
    whatsappTemplate: `${notif.title}\n\n${notif.body}`,
    status: 'DISPATCHED_TO_WHATSAPP'
  }
}];

// Platform Error Context Extractor & Severity Classifier (Gap 1 & Gap 30)
const err = $input.first().json;
const traceId = `err_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`;
const nodeName = err.node?.name || 'PLATFORM_NODE';
const isCritical = nodeName.includes('Payment') || nodeName.includes('Inventory');

return [{
  json: {
    traceId: traceId,
    nodeName: nodeName,
    severity: isCritical ? 'CRITICAL' : 'ERROR',
    errorMessage: err.error?.message || 'Execution error',
    errorStack: err.error?.stack || null,
    shouldAlertAdmin: isCritical,
    timestamp: new Date().toISOString()
  }
}];

// Low-Noise Admin Telegram Alert (Gap 1)
const err = $('11a. Platform Error Extractor').first().json;
return [{
  json: {
    alertType: 'CRITICAL_PLATFORM_ERROR',
    text: "🚨 *ZEYTECH CRITICAL ALERT*\n• Node: *" + err.nodeName + "*\n• Severity: " + err.severity + "\n• Error: " + err.errorMessage + "\n• Trace ID: " + err.traceId,
    status: 'ALERT_DISPATCHED'
  }
}];
